import React, { useCallback, useEffect, useState } from 'react';
import { format, parseISO } from 'date-fns';
import { Button, Checkbox, Input, Select } from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { listT02Invoices, type T02InvoiceListItem } from '../../../services/kt/t02Invoices';
import df from '../../../styles/documentForm.module.css';

interface SearchState {
  ngayCt1: string;
  ngayCt2: string;
  maPost: string;
  maGd: string;
  soCt1: string;
  soCt2: string;
  locNsd: boolean;
}

const emptySearch = (): SearchState => ({
  ngayCt1: '',
  ngayCt2: '',
  maPost: '',
  maGd: '',
  soCt1: '',
  soCt2: '',
  locNsd: false,
});

function formatDate(value: string | null | undefined): string {
  if (!value) return '';
  try {
    const parsed = parseISO(value);
    if (Number.isNaN(parsed.getTime())) return value;
    return format(parsed, 'dd/MM/yyyy');
  } catch {
    return value;
  }
}

function buildSearchQuery(search: SearchState): Record<string, string | number | boolean> {
  const query: Record<string, string | number | boolean> = {};
  if (search.ngayCt1.trim()) query.ngayCt1 = search.ngayCt1.trim();
  if (search.ngayCt2.trim()) query.ngayCt2 = search.ngayCt2.trim();
  if (search.maPost === '3' || search.maPost === '9') query.maPost = search.maPost;
  if (search.maGd === '2') query.maGd = search.maGd;
  if (search.soCt1.trim()) query.soCt1 = search.soCt1.trim();
  if (search.soCt2.trim()) query.soCt2 = search.soCt2.trim();
  if (search.locNsd) query.locNsd = true;
  return query;
}

function Field(props: {
  label: string;
  testId: string;
  value: string;
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
  maxLength?: number;
  type?: string;
}) {
  return (
    <div>
      <label className={df.label}>{props.label}</label>
      <Input
        type={props.type}
        maxLength={props.maxLength}
        data-testid={props.testId}
        value={props.value}
        onChange={props.onChange}
      />
    </div>
  );
}

const T02ListPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const [search, setSearch] = useState<SearchState>(emptySearch);
  const [applied, setApplied] = useState<SearchState>(emptySearch);
  const [filtering, setFiltering] = useState(false);
  const [items, setItems] = useState<T02InvoiceListItem[]>([]);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const keepSelection = (rows: T02InvoiceListItem[], current: string) => {
    if (rows.some(row => row.sttRec === current)) return current;
    return '';
  };

  const loadOpen = useCallback(async (locNsd: boolean, current: string) => {
    setLoading(true);
    setError('');
    try {
      const query: Record<string, string | number | boolean> = { loadTop: 4 };
      if (locNsd) query.locNsd = true;
      const rows = await listT02Invoices(query);
      setItems(rows);
      setSelectedSttRec(keepSelection(rows, current));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(getApiErrorMessage(err, 'Không tải được danh sách cập nhập hóa đơn GTGT đầu ra'));
    } finally {
      setLoading(false);
    }
  }, []);

  const loadSearch = useCallback(async (currentSearch: SearchState, current: string) => {
    setLoading(true);
    setError('');
    try {
      const rows = await listT02Invoices(buildSearchQuery(currentSearch));
      setItems(rows);
      setSelectedSttRec(keepSelection(rows, current));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(getApiErrorMessage(err, 'Không tải được danh sách cập nhập hóa đơn GTGT đầu ra'));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadOpen(false, '');
  }, [loadOpen]);

  const setText = (key: keyof SearchState) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(prev => ({ ...prev, [key]: event.target.value }));
  };

  const onSearch = () => {
    setFiltering(true);
    setApplied(search);
    void loadSearch(search, selectedSttRec);
  };

  const onRefresh = () => {
    if (filtering) void loadSearch(applied, selectedSttRec);
    else void loadOpen(search.locNsd, selectedSttRec);
  };

  const onEnter = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter' && (event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement)) {
      event.preventDefault();
      onSearch();
    }
  };

  const noSelection = !selectedSttRec;

  return (
    <div className={df.page} data-testid="ct-t02-list">
      <h1 data-testid="ct-t02-title">Cập nhập hóa đơn GTGT đầu ra</h1>
      <div className={df.headerActions}>
        <Button variant="secondary" data-testid="ct-t02-toolbar-refresh-btn" onClick={onRefresh}>Làm mới</Button>
        <Button variant="primary" data-testid="ct-t02-search-btn" onClick={onSearch}>Tìm</Button>
        <Button variant="primary" data-testid="ct-t02-toolbar-add-btn" onClick={() => navigate('/kt/t02/them')}>Thêm</Button>
        <Button variant="secondary" data-testid="ct-t02-toolbar-edit-btn" disabled={noSelection} onClick={() => navigate(`/kt/t02/${selectedSttRec}`)}>Sửa</Button>
        <Button variant="secondary" data-testid="ct-t02-toolbar-view-btn" disabled={noSelection} onClick={() => navigate(`/kt/t02/${selectedSttRec}?mode=view`)}>Xem</Button>
        <Button variant="secondary" data-testid="ct-t02-toolbar-copy-btn" disabled={noSelection} onClick={() => navigate(`/kt/t02/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}>Sao chép</Button>
      </div>

      <section className={df.section} data-testid="ct-t02-search">
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <Field label="Ngày C.từ từ" testId="ct-t02-search-ngayCt1" type="date" value={search.ngayCt1} onChange={setText('ngayCt1')} />
          <Field label="Ngày C.từ đến" testId="ct-t02-search-ngayCt2" type="date" value={search.ngayCt2} onChange={setText('ngayCt2')} />
          <Select label="Mức xử lý" data-testid="ct-t02-search-maPost" value={search.maPost} options={[{ value: '', label: 'Tất cả' }, { value: '3', label: 'Lập chứng từ' }, { value: '9', label: 'Kê khai thuế' }]} onChange={event => setSearch(prev => ({ ...prev, maPost: event.target.value }))} />
          <Select label="Loại giao dịch" data-testid="ct-t02-search-maGd" value={search.maGd} options={[{ value: '', label: 'Tất cả' }, { value: '2', label: 'Kê khai thuế' }]} onChange={event => setSearch(prev => ({ ...prev, maGd: event.target.value }))} />
          <Field label="Số C.từ từ" testId="ct-t02-search-soCt1" maxLength={30} value={search.soCt1} onChange={setText('soCt1')} />
          <Field label="Số C.từ đến" testId="ct-t02-search-soCt2" maxLength={30} value={search.soCt2} onChange={setText('soCt2')} />
          <div>
            <Checkbox label="Chỉ chứng từ của tôi" data-testid="ct-t02-search-locNsd" checked={search.locNsd} onChange={event => setSearch(prev => ({ ...prev, locNsd: event.target.checked }))} />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      {loading ? <div className={df.loading}>Đang tải...</div> : null}
      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-t02-grid">
          <thead>
            <tr>
              <th style={{ width: 70 }}>Số C.từ</th>
              <th style={{ width: 70 }}>Ngày C.từ</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => (
              <tr
                key={row.sttRec}
                aria-selected={row.sttRec === selectedSttRec}
                style={row.sttRec === selectedSttRec ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                onClick={() => setSelectedSttRec(row.sttRec)}
              >
                <td>{row.soCt}</td>
                <td>{formatDate(row.ngayCt)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {!loading && items.length === 0 ? (
        <div>{filtering ? 'Không tìm thấy cập nhập hóa đơn GTGT đầu ra' : 'Không có cập nhập hóa đơn GTGT đầu ra'}</div>
      ) : null}
    </div>
  );
};

export default T02ListPage;
